import { defineDynamic, defineInstructions } from "eve/instructions";

import { container } from "../../src/composition/container";

// The generated-UI library's instructions, generated by OpenUI from the same component library the
// chat renders, so the model and the renderer share one vocabulary. They are part of every prompt
// and count toward the context budget (measured in docs/notes/openui-spike.md). Read at runtime,
// not at build time, so building the agent never constructs the container.
export default defineDynamic(() => defineInstructions({ content: container().generatedUiInstructions }));
